#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main() {
    char s[50]; if (scanf("%s", s) != 1) return 0;
    long long n = atoll(s);
    int d = strlen(s);
    long long seq[1000];
    for (int i = 0; i < d; i++) seq[i] = s[i] - '0';
    int len = d;
    while (seq[len - 1] < n) {
        long long next_v = 0;
        for (int i = len - d; i < len; i++) next_v += seq[i];
        seq[len++] = next_v;
    }
    printf("%s\n", seq[len - 1] == n ? "YES" : "NO");
    return 0;
}

