#include <vector>
#include <numeric>
using namespace std;
int main() {
    string s; if (cin >> s) {
        long long n = stoll(s);
        int d = s.length();
        vector<long long> seq;
        for (char c : s) seq.push_back(c - '0');
        while (seq.back() < n) {
            long long sum_d = 0;
            for (size_t i = seq.size() - d; i < seq.size(); i++) sum_d += seq[i];
            seq.push_back(sum_d);
        }
        cout << (seq.back() == n ? "YES" : "NO") << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.ArrayList;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            long n = Long.parseLong(s);
            int d = s.length();
            ArrayList<Long> seq = new ArrayList<>();
            for (char c : s.toCharArray()) seq.add((long)(c - '0'));
            while (seq.get(seq.size() - 1) < n) {
                long sum = 0;
                for (int i = seq.size() - d; i < seq.size(); i++) sum += seq.get(i);
                seq.add(sum);
            }
            System.out.println(seq.get(seq.size() - 1) == n ? "YES" : "NO");
        }
    }
}

